using System.Text;

public static class IbanStore
{
    // Looks scrambled in the database; anyone can reverse it
    public static string Encrypt(string iban) =>
        Convert.ToBase64String(Encoding.UTF8.GetBytes(iban));

    public static string Decrypt(string stored) =>
        Encoding.UTF8.GetString(Convert.FromBase64String(stored));
}

using Microsoft.AspNetCore.DataProtection;

public sealed class IbanStore(IDataProtectionProvider provider)
{
    // AES-256-CBC + HMACSHA256 by default, with managed key rotation
    private readonly IDataProtector _protector =
        provider.CreateProtector("Payouts.Iban.v1");

    public string Protect(string iban) => _protector.Protect(iban);

    // Throws CryptographicException if the value was tampered with
    public string Unprotect(string stored) => _protector.Unprotect(stored);
}
